LESSONS['5-4'] = { title: ['Masalah garam', 'Salt problems', '盐分问题'], body: [
  ['table', { head: [['Tanda', 'Signs', '迹象'], ['Punca', 'Cause', '原因']],
    rows: [[['Pokok layu walaupun tanah lembap; percambahan lemah; pertumbuhan terbantut', 'Plants wilt although the soil is moist; poor germination; stunted growth', '土壤湿润而植株仍萎蔫；发芽差；生长受阻'],
            ['Air laut di tanah pantai; air pengairan yang masin; baja berlebihan, terutamanya dalam polibeg dan fertigasi', 'Seawater on coastal land; salty irrigation water; too much fertiliser, especially in polybags and fertigation', '沿海土地受海水影响；灌溉水含盐；施肥过量，尤其是育苗袋和灌溉施肥']]] }],
  ['p', ['Garam dalam zon akar menyukarkan akar menyerap air, jadi tanda-tandanya boleh disalah anggap sebagai kemarau atau kekurangan nutrien. Sebelum menambah baja pada pokok yang kelihatan tidak sihat, periksa garam dan keadaan akar.',
         'Salts in the root zone make it hard for roots to take up water, so the signs can be mistaken for drought or a nutrient deficiency. Before adding fertiliser to an unhealthy-looking plant, check for salts and look at the roots.',
         '根区的盐分使根系难以吸水，因此症状容易被误认为干旱或缺素。在给看起来不健康的植株追肥之前，应先检查盐分和根系状况。']],
  ['h', ['Mengukur garam: kekonduksian elektrik', 'Measuring salt: electrical conductivity', '测量盐分：电导率']],
  ['p', ['Kemasinan diukur sebagai kekonduksian elektrik (EC), dalam dS/m. Makmal mengukurnya pada ekstrak tanah tepu; meter mudah alih yang menggunakan campuran tanah dan air memberi bacaan yang lebih rendah dan tidak boleh dibandingkan terus dengan jadual ini.',
         'Salinity is measured as electrical conductivity (EC), in dS/m. A laboratory measures it on a saturated soil extract; a portable meter used on a soil-and-water mixture reads lower and cannot be compared directly with this table.',
         '盐分以电导率（EC）衡量，单位为 dS/m。实验室测的是饱和土浸提液；用土水混合液测量的便携式仪器读数较低，不能直接与此表比较。']],
  ['table', { head: [['EC ekstrak tanah tepu', 'EC of saturated soil extract', '饱和浸提液 EC'], ['Kesan', 'Effect', '影响']],
    rows: [
      ['2 – 4 dS/m', ['Menjejaskan sesetengah tanaman', 'Affects some crops', '影响部分作物']],
      ['4 – 5 dS/m', ['Menjejaskan banyak tanaman', 'Affects many crops', '影响许多作物']],
      ['> 8 dS/m', ['Menjejaskan semua kecuali tanaman yang sangat tahan', 'Affects all but very tolerant crops', '除极耐盐作物外都受影响']],
    ] }],
  ['table', { head: [['EC air pengairan', 'EC of irrigation water', '灌溉水 EC'], ['Had penggunaan', 'Limitation', '使用限制']],
    rows: [
      ['≤ 0.75 dS/m', ['Tiada had', 'None', '无限制']],
      ['≥ 3.0 dS/m', ['Teruk', 'Severe', '严重']],
    ] }],
  ['src', { s: 'Colorado State University Extension, Irrigation water quality criteria; Oregon State University Extension PNW 601', u: 'https://extension.colostate.edu/resource/irrigation-water-quality-criteria',
    a: ['Garis panduan umum dari Amerika Syarikat; toleransi berbeza mengikut tanaman.', 'General guidelines from the United States; tolerance differs by crop.', '来自美国的一般准则；耐受性因作物而异。'] }],
  ['h', ['Apa yang boleh dibuat', 'What to do', '可以怎么做']],
  ['ul', [
    ['Uji air pengairan untuk garam sebelum menggunakannya, terutamanya air telaga berhampiran pantai.', 'Test irrigation water for salt before using it, especially well water near the coast.', '灌溉水使用前应检测盐分，尤其是沿海的井水。'],
    ['Beri baja dalam dos yang lebih kecil dan lebih kerap, dan jangan melebihi kadar yang disyorkan.', 'Give fertiliser in smaller, more frequent doses, and do not exceed the recommended rate.', '肥料少量多次施用，不要超过推荐用量。'],
    ['Di mana saliran membenarkan, air yang baik atau hujan akan melarut resap garam keluar dari zon akar.', 'Where drainage allows, good-quality water or rain will leach salts out of the root zone.', '在排水条件许可的地方，优质水或雨水可把盐分淋洗出根区。'],
    ['Anak benih paling sensitif; lindungi semaian daripada air masin.', 'Seedlings are the most sensitive; protect nurseries from salty water.', '幼苗最敏感；要防止苗圃接触含盐的水。'],
  ]],
] };
UNITS.find(u => u.n === 5).lessons.push('5-4');
UNITS.find(u => u.n === 3).blurb = ['Pemeriksaan di lapangan, persampelan, mengenal tanah Malaysia, dan tanah gambut serta asid sulfat.', 'Field checks, sampling, identifying Malaysian soils, and peat and acid sulfate soils.', '田间检查、取样、辨识马来西亚土壤，以及泥炭土和酸性硫酸盐土。'];
UNITS.find(u => u.n === 5).blurb = ['Disusun mengikut masalah: keasidan, kurang bahan organik, air, pemadatan dan garam.', 'Organised by problem: acidity, low organic matter, water, compaction and salt.', '按问题编排：酸性、有机质不足、水分、压实和盐分。'];

