UNITS.find(u => u.n === 6).blurb = ['Nutrien, tanda kekurangan, jenis baja, baja cecair buatan sendiri, cara membaja dan pengiraan.', 'Nutrients, deficiency signs, fertiliser types, home-made liquid fertilisers, application and calculations.', '养分、缺乏症状、肥料种类、自制液体肥、施肥方法和用量计算。'];

/* the risks of each kind of fertiliser, added to the lesson on fertiliser types */
LESSONS['6-2'].body.push(
  ['h', ['Risiko bahan organik', 'Risks of organic materials', '有机材料的风险']],
  ['ul', [
    ['**Biji rumpai**: pencernaan ternakan tidak memusnahkan semua biji benih, jadi baja kandang boleh membawa rumpai ke ladang.', '**Weed seeds**: livestock digestion does not destroy every seed, so manure can carry weeds into the field.', '**杂草种子**：牲畜的消化并不能杀死所有种子，因此厩肥可能把杂草带入田间。'],
    ['**Patogen**: baja kandang mentah boleh membawa E. coli, Salmonella dan Listeria. Ini paling penting bagi sayur yang dimakan mentah.', '**Pathogens**: raw manure can carry E. coli, Salmonella and Listeria. This matters most for vegetables eaten raw.', '**病原菌**：生粪可能带有大肠杆菌、沙门氏菌和李斯特菌，对生食蔬菜尤其重要。'],
    ['**Akar dan daun terbakar**: baja kandang segar tinggi ammonia dan garam.', '**Root and leaf burn**: fresh manure is high in ammonia and salts.', '**烧根烧叶**：鲜粪含氨和盐分高。'],
    ['**Sisa racun rumpai** dalam baja kandang atau jerami boleh merosakkan tanaman.', '**Herbicide residues** in manure or straw can damage crops.', '厩肥或稻草中的**除草剂残留**可能伤害作物。'],
  ]],
  ['p', ['Pengkomposan yang betul mengurangkan risiko ini. Timbunan perlu menjadi panas, sekitar 55 hingga 68 °C, dan dibalikkan supaya semua bahan melalui haba itu, kemudian dibiarkan matang sebelum digunakan.',
         'Proper composting reduces these risks. The heap has to get hot, around 55 to 68 °C, and be turned so that all the material passes through that heat, then left to mature before use.',
         '正确堆肥可降低这些风险。堆体须升温至约 55 至 68 °C，并经翻堆使所有物料都经过高温，之后还要熟化才可使用。']],
  ['src', { s: 'Colorado State University Extension, Using manure in gardens; University of Arizona Extension; University of Connecticut Soil Testing Laboratory', u: 'https://extension.colostate.edu/resource/using-manure-in-colorado-gardens/',
    a: ['Panduan umum; suhu yang diberi berbeza sedikit antara sumber.', 'General guidance; the temperatures given differ slightly between sources.', '一般指引；各来源给出的温度略有不同。'] }],
  ['h', ['Apabila baja kimia digunakan berlebihan', 'When chemical fertiliser is overused', '化肥过量使用的后果']],
  ['ul', [
    ['**Keasidan tanah**: baja nitrogen berasaskan ammonium menjadikan tanah lebih berasid dari tahun ke tahun.', '**Soil acidity**: ammonium-based nitrogen fertilisers make the soil more acidic year after year.', '**土壤酸化**：铵态氮肥会使土壤逐年变酸。'],
    ['**Pencemaran air**: nitrat terlarut resap ke dalam air bawah tanah, dan fosforus yang dihanyutkan ke sungai serta tasik menyebabkan ledakan alga.', '**Water pollution**: nitrate leaches into groundwater, and phosphorus washed into rivers and lakes causes algal blooms.', '**水体污染**：硝酸盐淋入地下水，被冲入河流湖泊的磷则引起藻类暴发。'],
    ['**Kecederaan garam**: baja yang terlalu banyak atau terlalu dekat dengan benih dan akar menarik air keluar daripadanya.', '**Salt injury**: too much fertiliser, or fertiliser too close to seeds and roots, draws water out of them.', '**盐害**：肥料过多，或离种子和根太近，会把其中的水分吸走。'],
    ['**Kos**: nutrien yang tidak diambil oleh tanaman ialah wang yang terbuang.', '**Cost**: nutrients the crop does not take up are money wasted.', '**成本**：作物没有吸收的养分就是浪费的金钱。'],
  ]],
  ['src', { s: 'Agriculture Victoria, Soil acidity; University of Hawai‘i CTAHR SA-12 (nitrate pollution); Top Crop Manager (salt injury)', u: 'https://agriculture.vic.gov.au/farm-management/soil/soil-acidity',
    a: ['Kesan umum; magnitudnya bergantung pada tanah, hujan dan kadar.', 'General effects; their size depends on soil, rainfall and rate.', '一般性影响；其程度取决于土壤、降雨和用量。'] }],
);


QUIZ[2].push(
  Q(['Tanah mengandungi 66% pasir, 20% kelodak dan 14% liat. Apakah kelas teksturnya?', 'A soil has 66% sand, 20% silt and 14% clay. What is its texture class?', '某土壤含 66% 砂粒、20% 粉粒和 14% 黏粒，属于哪一质地类别？'],
    [['Lom berpasir', 'Sandy loam', '砂质壤土'], ['Lom liat berpasir', 'Sandy clay loam', '砂质黏壤土'], ['Pasir berlom', 'Loamy sand', '壤质砂土'], ['Lom', 'Loam', '壤土']],
    ['Lom liat berpasir memerlukan sekurang-kurangnya 20% liat; sampel ini hanya 14%.', 'Sandy clay loam needs at least 20% clay; this sample has only 14%.', '砂质黏壤土要求黏粒至少 20%，而此样本只有 14%。']));
QUIZ[5].push(
  Q(['Kaedah pengairan yang manakah paling sesuai untuk tanah berpasir?', 'Which irrigation method suits sandy soil best?', '哪一种灌溉方法最适合砂质土？'],
    [['Renjis atau titis, sedikit tetapi kerap', 'Sprinkler or drip, little and often', '喷灌或滴灌，少量多次'], ['Petak bertakung', 'Flooded basins', '淹水格田'], ['Alur panjang', 'Long furrows', '长沟灌'], ['Tiada pengairan', 'No irrigation', '不灌溉']],
    ['Tanah berpasir menyerap air dengan cepat dan menyimpan sedikit, jadi air permukaan hilang sebelum sampai ke hujung ladang.', 'Sandy soil takes in water fast and stores little, so surface water is lost before it reaches the end of the field.', '砂质土入渗快、储水少，地面水还没流到田尾就渗失了。']));
QUIZ[6].push(
  Q(['Mengapa penutup bekas FPJ tidak boleh diketatkan?', 'Why must the lid of an FPJ container never be tightened?', '为什么 FPJ 容器的盖子不能拧紧？'],
    [['Mikrob terus menghasilkan gas dan bekas boleh meletup', 'The microbes keep producing gas and the container can burst', '微生物持续产气，容器可能爆裂'], ['Cahaya perlu masuk', 'Light has to get in', '需要透光'], ['Gula akan menghablur', 'The sugar would crystallise', '糖会结晶'], ['Air akan tersejat terlalu cepat', 'The water would evaporate too fast', '水分会蒸发太快']],
    ['Penapaian berterusan selepas ditapis, jadi gas mesti dapat keluar.', 'Fermentation goes on after straining, so the gas has to escape.', '过滤之后发酵仍在继续，因此必须让气体排出。']),
  Q(['Mengapa baja kandang mentah berisiko pada sayur yang dimakan mentah?', 'Why is raw manure a risk on vegetables eaten raw?', '为什么生粪对生食蔬菜有风险？'],
    [['Ia boleh membawa patogen seperti E. coli dan Salmonella', 'It can carry pathogens such as E. coli and Salmonella', '它可能带有大肠杆菌、沙门氏菌等病原菌'], ['Ia menjadikan sayur pahit', 'It makes the vegetables bitter', '它会使蔬菜变苦'], ['Ia menurunkan pH kepada 3', 'It lowers the pH to 3', '它把 pH 降到 3'], ['Ia tidak mengandungi nutrien', 'It contains no nutrients', '它不含养分']],
    ['Pengkomposan yang betul memanaskan bahan dan memusnahkan patogen serta biji rumpai.', 'Proper composting heats the material and destroys pathogens and weed seeds.', '正确堆肥会使物料升温，杀死病原菌和杂草种子。']));

/* ---------- Soil colour ---------- */
LESSONS['2-6'] = { title: ['Warna tanah', 'Soil colour', '土壤颜色'], body: [
  ['p', ['Warna ialah petunjuk pertama tentang sesuatu tanah, dan ia percuma. Ia menunjukkan bahan organik, keadaan besi dan saliran. Ia tidak mengukur kesuburan: gunakannya untuk memutuskan apa yang perlu diperiksa seterusnya.',
         'Colour is the first clue to a soil, and it costs nothing. It points to organic matter, the state of the iron and the drainage. It does not measure fertility: use it to decide what to check next.',
         '颜色是了解土壤的第一条线索，而且不花钱。它反映有机质、铁的状态和排水状况。它并不能衡量肥力，而是用来决定接下来该检查什么。']],
  ['table', { head: [['Warna', 'Colour', '颜色'], ['Apa yang ditunjukkan', 'What it indicates', '说明什么']],
    rows: [
      [['Hitam dan perang gelap', 'Black and dark brown', '黑色和深棕色'], ['Bahan organik. Humus, peringkat akhir pereputan, berwarna hitam.', 'Organic matter. Humus, the last stage of decay, is black.', '有机质。腐殖质是分解的最后阶段，呈黑色。']],
      [['Merah', 'Red', '红色'], ['Oksida besi yang terbentuk di tanah yang bersaliran baik, tempat udara mencukupi.', 'Iron oxides formed in well-drained soil, where air is plentiful.', '在排水良好、空气充足的土壤中形成的氧化铁。']],
      [['Kuning', 'Yellow', '黄色'], ['Oksida besi yang terbentuk dalam keadaan udara dan lembapan sederhana; lebih lembap daripada tanah merah.', 'Iron oxide formed under moderate air and moisture; wetter than a red soil.', '在空气和水分适中的条件下形成的氧化铁；比红土更潮湿。']],
      [['Kelabu atau kelabu kebiruan', 'Grey or bluish-grey', '灰色或蓝灰色'], ['Besi dalam keadaan terturun kerana tanah tepu air dan kurang udara. Tanda saliran yang lemah.', 'Iron in a reduced state because the soil is waterlogged and short of air. A sign of poor drainage.', '因土壤积水缺氧，铁处于还原状态。这是排水不良的迹象。']],
      [['Putih atau pucat', 'White or pale', '白色或浅色'], ['Di Malaysia, lazimnya liat kaolinit yang rendah besi; kaolin tulen berwarna putih. Tanah berpasir yang pucat, seperti BRIS dan bekas lombong, ialah pasir kuarza. Kerak garam putih hanya ditemui berhampiran laut.', 'In Malaysia, usually kaolinite clay that is low in iron; pure kaolin is white. Pale sandy soil, such as BRIS and tin tailings, is quartz sand. White salt crusts are found only near the sea.', '在马来西亚，通常是含铁少的高岭石黏土；纯高岭土为白色。浅色的砂质土（如 BRIS 和锡矿尾砂）是石英砂。白色盐结皮只见于海边。']],
      [['Bintik-bintik', 'Mottles', '斑纹'], ['Tompok warna yang berbeza, seperti kuning dalam tanah kelabu kebiruan, menandakan tanah yang tepu air dari semasa ke semasa.', 'Patches of a contrasting colour, such as yellow in a bluish-grey soil, signal a soil that is waterlogged from time to time.', '颜色对比明显的斑块（如蓝灰色土中的黄斑）表示土壤时常积水。']],
    ] }],
  ['src', { s: 'Agriculture Victoria, Victorian Resources Online: Soil colour; kaolin colour after Wikipedia, Kaolinite', u: 'https://soilhealth.ccmaknowledgebase.vic.gov.au/vro_archive/statewide/pages/soilhealth_prac_soil_colour.html',
    a: ['Tafsiran umum; warna yang sama boleh mempunyai lebih daripada satu punca.', 'General interpretation; the same colour can have more than one cause.', '一般性解释；同一种颜色可能有不止一种成因。'] }],
  ['p', ['Tanah yang bersaliran baik biasanya mempunyai warna yang terang dan sekata. Kebanyakan tanah tanah tinggi di Malaysia berwarna merah hingga kuning kerana oksida besi.',
         'Well-drained soils usually have bright, even colours. Most upland soils in Malaysia are red to yellow because of iron oxides.',
         '排水良好的土壤通常颜色鲜明而均匀。马来西亚大部分高地土壤因含氧化铁而呈红色至黄色。']],
  ['h', ['Carta warna Munsell', 'The Munsell colour chart', '蒙赛尔土色卡']],
  ['p', ['Untuk mengelakkan nama warna yang berbeza antara orang, ahli sains tanah memadankan tanah dengan cip warna dalam carta Munsell dan menulis tiga nilai.',
         'To avoid colour names that differ from person to person, soil scientists match the soil to a colour chip in the Munsell chart and write down three values.',
         '为了避免各人对颜色的叫法不同，土壤学家把土壤与蒙赛尔土色卡上的色片对照，并记下三个数值。']],
  ['table', { head: [['Bahagian', 'Part', '组成'], ['Maksud', 'Meaning', '含义'], ['Dalam 10YR 5/4', 'In 10YR 5/4', '以 10YR 5/4 为例']],
    rows: [
      [['Hue', 'Hue', '色相 (Hue)'], ['Warna utama; dalam tanah biasanya kuning atau merah', 'The dominant colour; in soil usually yellow or red', '主要颜色；土壤中通常为黄或红'], '10YR'],
      [['Value', 'Value', '明度 (Value)'], ['Cerah atau gelap, dari 0 (hitam) hingga 10 (putih)', 'Lightness, from 0 (black) to 10 (white)', '明暗程度，从 0（黑）到 10（白）'], '5'],
      [['Chroma', 'Chroma', '彩度 (Chroma)'], ['Kekuatan atau ketulenan warna', 'The strength or purity of the colour', '颜色的强度或纯度'], '4'],
    ] }],
  ['p', ['Notasi ditulis sebagai hue, kemudian value dan chroma dipisahkan dengan garis condong. 10YR 5/4 ialah perang kekuningan.',
         'The notation is written as the hue, then the value and chroma separated by a slash. 10YR 5/4 is yellowish brown.',
         '记法是先写色相，再写明度和彩度，中间用斜线隔开。10YR 5/4 是黄棕色。']],
  ['h', ['Cara memerhati warna', 'How to observe colour', '如何观察颜色']],
  ['steps', [
    ['Pecahkan segumpal tanah untuk mendapat permukaan yang segar. Jangan gunakan permukaan yang dipotong atau disapu.', 'Break a clod open to get a fresh surface. Do not use a cut or smeared face.', '把土块掰开，取新鲜的断面。不要用切过或抹平的面。'],
    ['Perhatikan tanah dalam keadaan lembap; tanah menjadi lebih gelap apabila dibasahkan, jadi catat keadaannya.', 'Look at the soil when it is moist; soil darkens as it is wetted, so note its condition.', '在湿润状态下观察；土壤湿润后颜色变深，所以要注明其状态。'],
    ['Padankan dengan cip carta, atau gunakan nama warna yang mudah jika tiada carta.', 'Match it to a chart chip, or use a simple colour name if there is no chart.', '与色卡上的色片对照；没有色卡时用简单的颜色名称。'],
    ['Periksa setiap lapisan profil, bukan permukaan sahaja, dan catat sebarang bintik.', 'Check every layer of the profile, not only the surface, and record any mottles.', '检查剖面的每一层，而不只是表层，并记录任何斑纹。'],
  ]],
  ['src', { s: 'Agriculture Victoria, Victorian Resources Online: Soil colour; Munsell notation as used in soil survey', u: 'https://en.wikipedia.org/wiki/Soil_color',
    a: ['Amalan tinjauan tanah yang digunakan di seluruh dunia.', 'Soil survey practice used worldwide.', '全球通用的土壤调查做法。'] }],
] };
UNITS.find(u => u.n === 2).lessons.push('2-6');
UNITS.find(u => u.n === 2).blurb = ['Tekstur, struktur, air, pH dan warna: sifat yang menentukan cara tanah berkelakuan.', 'Texture, structure, water, pH and colour: the properties that decide how a soil behaves.', '质地、结构、水分、酸碱度和颜色：决定土壤表现的性质。'];

QUIZ[2].push(
  Q(['Lapisan tanah berwarna kelabu kebiruan dengan bintik kuning. Apakah yang ditunjukkan?', 'A soil layer is bluish-grey with yellow mottles. What does that indicate?', '某土层呈蓝灰色并带黄色斑纹，这说明什么？'],
    [['Saliran lemah; tanah itu kerap tepu air', 'Poor drainage; the soil is often waterlogged', '排水不良；土壤经常积水'], ['Bahan organik yang tinggi', 'High organic matter', '有机质含量高'], ['Terlalu banyak baja', 'Too much fertiliser', '肥料过多'], ['Tanah berpasir yang cepat kering', 'Sandy soil that dries fast', '易干的砂质土']],
    ['Tanpa udara, besi berubah kepada bentuk terturun yang berwarna kelabu.', 'Without air, iron changes to a reduced form that is grey.', '缺氧时，铁转变为呈灰色的还原态。']));
QUIZ[4].push(
  Q(['Dalam persamaan A = R × K × LS × C × P, faktor manakah yang paling mudah diubah oleh petani?', 'In the equation A = R × K × LS × C × P, which factors can a grower change most easily?', '在方程 A = R × K × LS × C × P 中，种植者最容易改变哪些因子？'],
    [['C dan P: litupan dan amalan pemuliharaan', 'C and P: cover and conservation practice', 'C 和 P：覆盖与保育措施'], ['R: hujan', 'R: rainfall', 'R：降雨'], ['K: jenis tanah', 'K: soil type', 'K：土壤类型'], ['Tiada satu pun', 'None of them', '都不能']],
    ['Hujan dan jenis tanah tidak boleh dipilih, tetapi litupan dan amalan boleh.', 'Rainfall and soil type cannot be chosen, but cover and practice can.', '降雨和土壤类型无法选择，但覆盖和措施可以。']));

